theorem BitVec.setWidth_append {w v k : ℕ} {x : BitVec w} {y : BitVec v} :
  BitVec.setWidth k (x ++ y) =
    if h : k ≤ v then BitVec.setWidth k y else BitVec.cast ⋯ (BitVec.setWidth (k - v) x ++ y)

