theorem BitVec.toFin_sshiftRight' {w : ℕ} {x y : BitVec w} :
  (x.sshiftRight' y).toFin =
    if x.msb = true then Fin.ofNat (2 ^ w) (2 ^ w - 1 - (2 ^ w - 1 - x.toNat) >>> y.toNat)
    else Fin.ofNat (2 ^ w) (x.toNat >>> y.toNat)

